using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class BallSpinChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  foreach(int sign in new[]{-1,1}){var gesture=new CircleGesture();int result=0,hits=0;for(int i=0;i<=40;i++){float a=i*Mathf.PI/20*sign;if(gesture.Sample(new Vector3(Mathf.Cos(a)*4,10+Mathf.Sin(a)*4,14),i*.1f,out int turn)){result=turn;hits++;}}Require(hits==1&&result==sign,"Closed circle direction was not recognized once");}
  foreach(int kind in new[]{0,1,2,3,4}){var g=new CircleGesture();bool hit=false;for(int i=0;i<64;i++){float a=i*Mathf.PI/20;var p=kind==0?new Vector3(i*.2f,10,14):kind==1?new Vector3(Mathf.Sin(i)*.15f,10+Mathf.Cos(i)*.15f,14):kind==2?new Vector3(Mathf.Cos(a)*4,10+Mathf.Sin(a)*4,14+i*.3f):new Vector3(Mathf.Cos(a)*4,10+Mathf.Sin(a)*4,14);float time=kind==3?i*.01f:i*.1f;if(kind==4&&i%3==0)p+=Vector3.right*20;hit|=g.Sample(p,time,out _);}Require(!hit,"Line/jitter/depth/fast/jump gesture accepted: "+kind);}
  var old=JsonUtility.FromJson<WorldPlayMemory>("{}");Require(old.Valid()&&old.Spin.spins==0,"Historical play save rejected");var m=new SpinMemory{cues=1};m.Complete(-1);Require(m.Valid()&&m.spins==1&&m.lastDirection==-1,"Spin outcome invalid");m.spins=2;Require(!m.Valid(),"Invented spin accepted");var s=new SliceState();s.Hybrid.receipt=new ActionReceipt{action=CreatureAction.PlayWithToy,spin=true};Require(s.Valid(),"Spin receipt rejected");s.Hybrid.receipt.chased=true;Require(!s.Valid(),"Spin and chase lesson conflated");Debug.Log("BWVR_SPIN_MODEL_PASS: both circles, once-only recognition, line/jitter/depth/fast/teleport rejection, old saves and typed learning");
 }
 public static void Verify(Action<BeachBall> capture=null){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();slice.SetSanctuaryOpen(false);var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var ball=slice.GetComponentInChildren<BeachBall>();var item=ball.GetComponent<CarryItem>();var spin=ball.Spin;var nav=god.GetComponent<IslandNavigator>();float unit=nav.world.Scale;var motion=god.GetComponentInChildren<HumanoidMotion>();var animator=god.GetComponentInChildren<Animator>();var field=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)field.GetValue(slice);var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(i=>i==null),"Release held objects first");var feedbackField=typeof(QuestSlice).GetField("feedbackReady",Flags);var oldFeedback=(float)feedbackField.GetValue(slice);var gp=god.transform.position;var gr=god.transform.rotation;var allowed=ball.Chase.InteractionAllowed;var people=slice.GetComponentsInChildren<VillagerSocial>();var points=people.Select(p=>p.transform.position).ToArray();var ideas=slice.GetComponentsInChildren<ConstructionInspiration>();var active=ideas.Select(i=>i.gameObject.activeSelf).ToArray();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);
  var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.05f,playPreference=1};Vector3 at=ball.Bowling.Start;Quaternion face=Quaternion.LookRotation(ball.Bowling.Forward);Vector3 lureFoot=at;bool captured=false;
  void Position(){Require(nav.world.Sample(at,nav.profile,4,out var safe),"No safe spin spot");god.transform.SetPositionAndRotation(nav.world.ProjectFoot(safe,nav.profile),face);nav.ResetRoute();lureFoot=god.transform.position;typeof(HumanoidMotion).GetMethod("LateUpdate",Flags).Invoke(motion,null);typeof(HumanoidMotion).GetMethod("LateUpdate",Flags).Invoke(motion,null);}
  void Hold(float angle){ball.transform.position=lureFoot+face*new Vector3(Mathf.Cos(angle)*4,10+Mathf.Sin(angle)*4,14)*unit;}
  void Tick(float dt,bool ai=true){ball.Advance(dt,test.paused);if(ai)god.Tick(dt);else if(!test.paused)test.Hybrid.time+=dt;}
  string trace="";void Draw(int sign,bool ai=true){for(int i=0;i<=40;i++){Hold(i*Mathf.PI/20*sign);Tick(.1f,ai);if(i%5==0)trace+=" / "+i+"="+mind.Current+" ready="+spin.Ready+" drawing="+spin.Drawing+" spins="+test.WorldPlay.Spin.spins+" yaw="+god.transform.eulerAngles.y+" pos="+nav.world.ToNav(god.transform.position);}}
  void Cool(){for(int i=0;i<130;i++)Tick(.1f,false);Position();}
  try{
   god.Interrupt("Spin QA");field.SetValue(slice,test);god.NewSeason();ball.ResetWorld();foreach(var idea in ideas)idea.gameObject.SetActive(false);foreach(var p in people){p.ResetTask();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();p.transform.position+=Vector3.right*unit*300;}foreach(var a in cooldowns.Keys)if(a!=ball.GetComponent<CreatureAffordance>())a.cooldown=10000;Position();
   var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);Require((bool)typeof(QuestSlice).GetMethod("TryGrab",Flags).Invoke(slice,new object[]{1,item}),"Native toy pickup failed");
   for(int turn=0;turn<2;turn++){
    Position();Draw(turn==0?1:-1);Require(spin.Active||spin.Ready,"Witnessed circle not offered: turn "+turn+" phase "+mind.Current+" cues "+test.WorldPlay.Spin.cues+" spins "+test.WorldPlay.Spin.spins+trace+" journal "+string.Join(" | ",god.Journal.Capture().Select(e=>e.kind+":"+e.reason)));
    bool selected=spin.Active,paused=false;for(int i=0;i<220&&test.WorldPlay.Spin.spins<turn+1;i++){Hold(0);Tick(.05f);selected|=mind.Current==CreatureCuriosity.Phase.SpinTrick;if(spin.Active&&spin.Turned>90&&!paused){test.paused=true;var rot=god.transform.rotation;float angle=spin.Turned;Tick(1);Require(god.transform.rotation==rot&&spin.Turned==angle,"Paused spin advanced");test.paused=false;paused=true;typeof(HumanoidMotion).GetMethod("LateUpdate",Flags).Invoke(motion,null);Require(animator.GetFloat("Speed")>.5f,"Stationary spin has no stepping pose");if(!captured){capture?.Invoke(ball);captured=true;}}}
    Require(selected&&paused&&test.WorldPlay.Spin.spins==turn+1&&test.WorldPlay.Spin.lastDirection==(turn==0?1:-1)&&test.Hybrid.receipt.spin,"Utility spin failed: "+mind.Current+" "+god.Explanation);Require(Vector3.Distance(spin.Origin,god.transform.position)<unit*.05f&&Quaternion.Angle(spin.StartRotation,god.transform.rotation)<.5f,"Spin moved/lifted actor or did not finish full turn");Require(held[1]==item&&item.held&&mind.Holding==null&&!test.Hybrid.receipt.chased&&!test.Hybrid.receipt.bowling,"Spin stole toy or learned another activity");Require(!slice.GiveFeedback(turn==0),"Feedback accepted while carrying");float preference=test.WorldPlay.Spin.preference;typeof(QuestSlice).GetMethod("Release",Flags).Invoke(slice,new object[]{1,new Ray(ball.transform.position+Vector3.up*unit*20,Vector3.down)});feedbackField.SetValue(slice,0f);Require(slice.GiveFeedback(turn==0)&&!slice.GiveFeedback(turn==0)&&!god.Feedback(turn==0)&&(turn==0?test.WorldPlay.Spin.preference>preference:test.WorldPlay.Spin.preference<preference),"Native one-shot contextual spin feedback missing");Require((bool)typeof(QuestSlice).GetMethod("TryGrab",Flags).Invoke(slice,new object[]{1,item}),"Toy re-grab after teaching failed");typeof(HumanoidMotion).GetMethod("LateUpdate",Flags).Invoke(motion,null);Require(animator.GetFloat("Speed")==0,"Stepping pose retained after spin");Cool();
   }
   Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Learned spin save invalid");int spins=test.WorldPlay.Spin.spins;Draw(1);for(int i=0;i<40&&!spin.Active;i++){Hold(0);Tick(.05f);}Require(spin.Active,"Interruption setup did not start spin");ball.Chase.InteractionAllowed=()=>false;Tick(.05f);Require(!spin.Active&&mind.Current==CreatureCuriosity.Phase.Rest&&test.WorldPlay.Spin.spins==spins&&!test.Hybrid.receipt.eligible&&held[1]==item,"Tracking/input loss left action or false reward");ball.Chase.InteractionAllowed=allowed;
   held[1]=null;item.held=false;item.GetComponent<Collider>().enabled=true;ball.ReturnHome();Position();Require(ball.Goals.Turns.Toggle(0),"Goal exclusion setup failed");Require((bool)typeof(QuestSlice).GetMethod("TryGrab",Flags).Invoke(slice,new object[]{1,item}),"Goal-turn toy grab failed");Draw(1);Require(!spin.Ready&&!spin.Active&&ball.Goals.Turns.PlayerOwnsTurn,"Circle displaced active goal game");ball.Goals.Turns.Cancel("QA complete");
   Debug.Log("BWVR_SPIN_PLAY_PASS: native held toy, utility-selected clockwise/counter turns, stepping pose, grounded stationary rotation, pause, exclusive ownership, typed once-only teaching/save, tracking cleanup and goal-game exclusion");
  }finally{feedbackField.SetValue(slice,oldFeedback);ball.Chase.InteractionAllowed=allowed;held[0]=held[1]=null;item.held=false;item.GetComponent<Collider>().enabled=true;god.Interrupt("Spin QA complete");ball.ReturnHome();field.SetValue(slice,original);god.NewSeason();for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(active[i]);foreach(var c in cooldowns)c.Key.cooldown=c.Value;god.transform.SetPositionAndRotation(gp,gr);nav.ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.position=points[i];people[i].GetComponent<IslandNavigator>().ResetRoute();}ball.ResetWorld();Physics.SyncTransforms();}
 }
}
}
